let nodes=0,ends=0;const endings=new Set();
const initial=mcpView(fresh());assert.equal(initial.board.plans.length,0);assert.equal(initial.board.work.length,0);assert.equal(initial.resources.business_slots_left,undefined);assert.ok(!JSON.stringify(initial).includes('移动送还'));assert.ok(!JSON.stringify(initial).includes('咖啡约定'));
function run(mode,seed=1){let s=fresh(),count=0;while(true){const v=view(s);nodes++;assert.deepEqual(view(JSON.parse(JSON.stringify(s))),v);assert.ok(v.stats.power>=0&&v.stats.power<=100);assert.ok(v.stats.parts>=0&&v.stats.cash>=0);assert.ok(v.stats.held>=0&&v.stats.held<=6);assert.ok(v.stats.prep>=0&&v.stats.prep<=3);assert.ok(v.stats.business_used<=3);assert.ok(!(v.stats.overtime&&v.stats.rescue_job));assert.equal(v.stats.cash,1050+v.stats.earned-v.stats.spent);assert.throws(()=>choose(s,'invalid'));if(!v.stats.quotes_known)assert.equal(v.board.plans.length,0);if(!v.stats.delivery_route)assert.ok(!v.board.plans.some(p=>p.id==='mobile'));if(v.stats.move_work&&!v.stats.stay_work)assert.ok(!v.board.plans.find(p=>p.id==='stay')?.ready);if(v.stats.preparation_closed)assert.equal(mcpView(s).resources.emergency_work_left,0);if([2,3].includes(v.stats.outcome))assert.equal(mcpView(s).resources.storage_capacity,3);if(v.ended){ends++;endings.add(v.stats.ending);assert.equal(v.stats.chapter,6);assert.ok(v.stats.day>=7);assert.equal(v.stats.business_used,3);assert.ok(v.history.length>25);assert.equal(mcpView(s).settlement.paid,v.stats.selected_cost);assert.equal(mcpView(s).settlement.cash_remaining,v.stats.cash);assert.equal(v.board.plans.length,0);if(mode==='BE-numeric')assert.equal(v.stats.ending,5);if(mode==='BE-expired')assert.equal(v.stats.ending,4);if(mode==='recover'||mode==='HE-move'||mode==='wrong-route')assert.equal(v.stats.ending,2);if(mode==='TE'||mode==='TE-tight'){assert.equal(v.stats.ending,3);assert.equal(v.stats.rescue_job,false);assert.equal(v.stats.overtime,false);}if(mode==='TE-tight')assert.equal(v.stats.power,0);if(mode==='switch'){assert.equal(v.stats.ending,1);assert.equal(v.stats.stay_work,1);assert.equal(v.stats.move_work,1);assert.equal(v.stats.cash,20);}return s;}
assert.ok(++count<130);let c;const pick=t=>v.choices.find(c=>c.text.includes(t));const title=v.scene.title;
if(mode!=='random'){
 if(title==='先选一个办法')c=pick(mode==='TE-tight'?'陪它练新手':'先修旧手');
 if(mode==='TE-tight'&&title==='第二章 · 寄给自己的包裹')c=pick('去问工坊');
 if(mode==='TE-tight'&&title==='她可以说不')c=pick('店铺继续寻找');
 if(title==='今天的店务时段'){
 const schedules={
 'HE-stay':['清点寄存并','完成接电','普通维修单'],
 'HE-move':['清点寄存并','完成装箱','休整充电'],
 'TE':['雇工坊做通用检查与搬迁','普通维修单','核对途中'],
 'TE-tight':['雇工坊做通用检查与搬迁','普通维修单','核对途中'],
 'BE-numeric':['休整充电','休整充电','买两枚'],
 'BE-expired':['清点寄存并','完成接电','普通维修单'],
 'recover':['清点寄存并','普通维修单','休整充电'],
 'switch':['雇工坊做通用检查与搬迁','普通维修单','完成接电'],
 'wrong-route':['雇工坊做通用检查与搬迁','普通维修单','休整充电']};
 c=pick(schedules[mode][v.stats.business_used]);if(!c)throw Error('Missing shop action '+mode+' '+JSON.stringify(v));}
 if(title==='来不了的人')c=pick(mode.startsWith('TE')?'送还路线':'取件、代管');
 if(title==='最后办理日'){c=mode==='BE-numeric'?pick('查看关店'):mode==='BE-expired'?pick('放弃继续营业'):mode==='recover'&&!v.stats.move_work?pick('加班完成装箱'):pick('结束办理');if(!c)throw Error('Missing final preparation '+mode+' '+JSON.stringify(v));}
 if(title==='确认接受尚未达标的结果？')c=pick('确认暂停');
 if(title==='确认暂停营业吗？')c=pick('确认暂停');
 if(title==='第六章 · 下一次，去哪里找你'){if(mode==='wrong-route')assert.ok(!pick('执行接电'));c=pick(mode.startsWith('BE')?'核对最后':mode.startsWith('TE')?'开始送还':['HE-stay','switch'].includes(mode)?'执行接电':'执行搬迁');if(!c)throw Error('Missing finale '+mode+' '+JSON.stringify(v));}
 c??=v.choices[0];
}
seed=(seed*1664525+1013904223)>>>0;c??=v.choices[(seed>>>16)%v.choices.length];const next=choose(s,c.id);assert.equal(next.revision,s.revision+1);assert.throws(()=>choose(next,c.id));assert.deepEqual(choose(JSON.parse(JSON.stringify(s)),c.id),next);s=next;}}
for(const mode of ['HE-stay','HE-move','TE','TE-tight','BE-numeric','recover','switch','wrong-route'])run(mode);for(let i=1;i<=20;i++)run('random',i);assert.equal(endings.size,4);
// Batch only explicitly annotated narrative: a sole consequential finale action must remain unchosen.
let bs=fresh();while(view(bs).scene.title!=='第六章 · 下一次，去哪里找你'){const v=view(bs);let c=v.choices[0];if(v.scene.title==='今天的店务时段')c=v.choices.find(c=>c.text.includes(['清点寄存并','完成装箱','休整充电'][v.stats.business_used]));if(v.scene.title==='最后办理日')c=v.choices.find(c=>c.text.includes('结束办理'));bs=chooseBatch(bs,c.id);assert.ok(bs.revision<100);}assert.equal(view(bs).choices.length,1);assert.equal(view(bs).choices[0].kind,'action');assert.equal(view(bs).stats.selected_cost,0);bs=chooseBatch(bs,view(bs).choices[0].id);assert.equal(view(bs).scene.title,'拆开第一箱');assert.equal(view(bs).choices.length,2);assert.equal(view(bs).stats.selected_cost,650);console.log(`Engine: ${nodes} states/${ends} runs; four revised first-part endings, route-switch work cost, hidden future info, aftermath, exact save, ledger, and mehumanful single-action batching passed.`);
const sql=new DatabaseSync(':memory:');sql.exec(fs.readFileSync('drizzle/0000_lovely_quentin_quire.sql','utf8'));
const DB={async batch(statements){sql.exec('BEGIN');try{const r=[];for(const s of statements)r.push(await s.run());sql.exec('COMMIT');return r;}catch(e){sql.exec('ROLLBACK');throw e;}},prepare(q){return {bind(...args){return {async first(){return sql.prepare(q).get(...args)},async all(){return {results:sql.prepare(q).all(...args)}},async run(){const r=sql.prepare(q).run(...args);return {meta:{changes:r.changes}};}};}};}};
async function call(path,method='GET',body,user='test-user',origin='https://test.example'){return worker.fetch(new Request('https://test.example'+path,{method,headers:{...(user?{'oai-authenticated-user-id':user}:{}),...(method==='POST'?{'Origin':origin,'Content-Type':'application/json'}:{})},...(method==='POST'?{body:JSON.stringify(body)}:{})}),{DB});}
assert.equal((await call('/api/state','GET',null,null)).status,401);let r=await call('/api/state');let s=await r.json();assert.equal(s.revision,0);const data={revision:0,choice:s.choices[0].id};assert.equal((await call('/api/choose','POST',data,'test-user','https://evil.example')).status,403);r=await call('/api/choose','POST',data);assert.equal(r.status,200);const after=await r.json();assert.equal(after.revision,1);assert.deepEqual(await (await call('/api/state')).json(),after);assert.equal((await call('/api/choose','POST',data)).status,409);assert.equal((await call('/api/choose','POST',{revision:1,choice:'junk'})).status,400);assert.equal((await (await call('/api/state','GET',null,'other-user')).json()).revision,0);assert.equal((await call('/api/restart','POST',{revision:1})).status,400);r=await call('/api/restart','POST',{revision:1,confirm:true});assert.equal(r.status,200);assert.equal((await r.json()).revision,2);assert.equal(sql.prepare('SELECT count(*) as n FROM archives').get().n,1);console.log('API: identity isolation, persistence, stale duplicate, bad choice, cross-origin rejection, restart confirmation and archive passed.');
const html=fs.readFileSync('src/index.html','utf8');new Function(html.match(/<script>([\s\S]*?)<\/script>/)[1]);console.log('Browser script syntax passed.');

const old={version:'pilot-1',revision:44,ink:'original old ink',scene:{title:'old ending',lines:['kept']},history:[{title:'old choice',lines:['test'],chosen:'keep'}]};sql.prepare('INSERT INTO saves(user_id,revision,payload,updated_at) VALUES(?,?,?,?)').run('old-user',44,JSON.stringify(old),'2026-10-03');const migrated=await (await call('/api/state','GET',null,'old-user')).json();assert.equal(migrated.version,VERSION);assert.equal(migrated.revision,45);const archived=await (await call('/api/archives','GET',null,'old-user')).json();assert.equal(archived.archives.length,1);assert.equal(archived.archives[0].scene.title,'old ending');await call('/api/state','GET',null,'old-user');assert.equal((await (await call('/api/archives','GET',null,'old-user')).json()).archives.length,1);assert.equal((await (await call('/api/archives','GET',null,'other-user')).json()).archives.length,0);assert.equal((await call('/api/choose','POST',{revision:44,choice:'44:0'},'old-user')).status,409);console.log('Old story migration: original snapshot preserved once, revision advanced, archive isolated per user, stale old-page choice rejected.');

// Real SDK protocol lifecycle against the same Worker through a Fetch adapter.
const {Client}=await import('@modelcontextprotocol/sdk/client/index.js');
const {StreamableHTTPClientTransport}=await import('@modelcontextprotocol/sdk/client/streamableHttp.js');
const http=await import('node:http');const hosts=[];
const makeClient=async(user)=>{const host=http.createServer(async(req,res)=>{try{let body='';for await(const c of req)body+=c;const headers=new Headers(req.headers);if(user)headers.set('oai-authenticated-user-id',user);const r=await worker.fetch(new Request('http://'+req.headers.host+req.url,{method:req.method,headers,...(body?{body}:{})}),{DB});res.writeHead(r.status,Object.fromEntries(r.headers));res.end(await r.text());}catch(e){res.writeHead(500);res.end(e.message);}});await new Promise(r=>host.listen(0,'127.0.0.1',r));hosts.push(host);const client=new Client({name:'integration-test',version:'1'});await client.connect(new StreamableHTTPClientTransport(new URL('http://127.0.0.1:'+host.address().port+'/mcp')));return client;};
const client=await makeClient('mcp-test');const list=await client.listTools();assert.deepEqual(list.tools.map(t=>t.name).sort(),['choose_game_action','get_game_state','restart_game','start_next_story']);let response=await client.callTool({name:'get_game_state',arguments:{}});let state=response.structuredContent;assert.equal(state.revision,0);assert.ok(!('ink' in state));let calls=0;const first={choice_id:state.choices[0].id,revision:state.revision};response=await client.callTool({name:'choose_game_action',arguments:first});assert.ok(!response.isError);state=response.structuredContent;calls++;assert.ok(state.revision>1);assert.ok(state.scenes.length>1);const readBack=(await client.callTool({name:'get_game_state',arguments:{}})).structuredContent;assert.deepEqual(readBack,state);assert.equal((await client.callTool({name:'choose_game_action',arguments:first})).isError,true);assert.equal((await client.callTool({name:'choose_game_action',arguments:{choice_id:'x',revision:-1}})).isError,true);while(!state.ended){assert.ok(calls<50);response=await client.callTool({name:'choose_game_action',arguments:{choice_id:state.choices[0].id,revision:state.revision}});assert.ok(!response.isError);state=response.structuredContent;calls++;}const webState=await (await call('/api/state','GET',null,'mcp-test')).json();assert.equal(webState.revision,state.revision);assert.equal(webState.ended,true);console.log(`MCP SDK: initialization, tool discovery, schema errors, repeated action rejection, saved batch replay and web-state parity passed. One full route: ${calls} choice calls for ${state.revision} narrative steps.`);await client.close();const unauth=await makeClient(null);await assert.rejects(()=>unauth.callTool({name:'get_game_state',arguments:{}}));await unauth.close();assert.equal((await worker.fetch(new Request('https://test.example/mcp',{method:'POST',headers:{Origin:'https://evil.example','Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'get_game_state',arguments:{}}})}),{DB})).status,403);console.log('MCP: unauthorized data call and cross-origin request rejected.');

for(const h of hosts)await new Promise(r=>h.close(r));

// Every event route is traversable with exact JSON saves and explicit costs.
const secondEndings=new Set();let eventStates=0;
function walkEvents(state,depth=0){const v=view(state);eventStates++;assert.ok(depth<30);assert.deepEqual(view(JSON.parse(JSON.stringify(state))),v);assert.ok(state.power>=0&&state.power<=100);if(v.ended){secondEndings.add(v.stats.ending);return;}assert.ok(v.choices.length>0);for(const choice of v.choices){const next=choose(state,choice.id);assert.equal(next.revision,state.revision+1);assert.throws(()=>choose(next,choice.id));walkEvents(next,depth+1);}}
for(const route of ['stay','move','mobile'])walkEvents(enterSequel(fresh(),route));
for(const end of [11,12,13,15])assert.ok(secondEndings.has(end));
assert.throws(()=>enterSequel(fresh(),'continue'));
let ev=await (await call('/api/state','GET',null,'sequel-test')).json();
assert.equal((await call('/api/sequel','POST',{revision:ev.revision,route:'stay'},'sequel-test')).status,400);
let r2=await call('/api/sequel','POST',{revision:ev.revision,route:'stay',confirm:true},'sequel-test');assert.equal(r2.status,200);ev=await r2.json();assert.equal(ev.episode,2);assert.equal((await call('/api/sequel','POST',{revision:ev.revision-1,route:'mobile',confirm:true},'sequel-test')).status,409);
assert.equal((await (await call('/api/archives','GET',null,'sequel-test')).json()).archives.length,1);
console.log(`Sequel: ${eventStates} exhaustive event states, route endings ${[...secondEndings]}, deterministic saves, valid choices and confirmed archived entry passed.`);
// Current first-part v5 saves retain their exact Ink bytecode and do not reset.
const {Story}=await import('inkjs');const oldContent=JSON.parse(fs.readFileSync('src/story-v5.json','utf8'));
let ls=new Story(oldContent),ll=[],lt='',lp='';while(ls.canContinue){const t=ls.Continue().trim();if(t)ll.push(t);for(const tag of ls.currentTags){if(tag.startsWith('title:'))lt=tag.slice(6);if(tag.startsWith('speaker:'))lp=tag.slice(8);}}
const legacyState={version:'part-one-routes-5',revision:71,ink:ls.state.ToJson(),scene:{lines:ll,title:lt,speaker:lp},history:[],lastDelta:[]};sql.prepare('INSERT INTO saves(user_id,revision,payload,updated_at) VALUES(?,?,?,?)').run('legacy-v5',71,JSON.stringify(legacyState),'2026-10-04');let lv=await(await call('/api/state','GET',null,'legacy-v5')).json();assert.equal(lv.version,'part-one-routes-5');assert.equal(lv.revision,71);assert.equal(lv.legacy,true);assert.equal((await(await call('/api/archives','GET',null,'legacy-v5')).json()).archives.length,0);assert.equal((await call('/api/choose','POST',{revision:71,choice:lv.choices[0].id},'legacy-v5')).status,200);
// New first-part survivors enter the matching continuation, with no arbitrary route swap.
for(const [mode,route] of [['HE-stay','stay'],['HE-move','move'],['TE','mobile']]){const end=run(mode);const next=enterSequel(end,'continue');assert.equal(next.route,route);assert.equal(next.revision,end.revision+1);}
assert.throws(()=>enterSequel(run('BE-numeric'),'continue'));
console.log('Legacy v5 preservation and first-part continuation-route parity passed.');
// Revised novel routes: late convergence, complete scenes, real inherited branch fields.
const {freshSequel:novelFresh}=await import('./src/sequel.js');
for(let mask=0;mask<32;mask++){const origin={demo:false,source:'test',brew:mask&1?'practice':'repair',seven:mask&2?'workshop':'shop',june:mask&4?'visit':'rest',mara:mask&8?'relay':'search',rivet:mask&16?'gift':'loan'};for(const route of ['stay','mobile']){let t=novelFresh(route,VERSION,origin);while(view(t).stats.chapter<5){assert.ok(t.node.startsWith(route+'_'));assert.ok(t.scene.lines.join('').length>500);assert.deepEqual(view(t).inheritance.choices,originChoices(origin));if(t.node==='mobile_market'&&origin.brew==='practice')assert.ok(!t.scene.lines.join('').includes('白港旧档案里那段'));t=choose(t,view(t).choices[0].id);}assert.equal(t.node,'gate');assert.equal(t.power,100);assert.equal(t.origin.brew,origin.brew);assert.ok(t.clues.some(c=>c.title===(origin.brew==='repair'?'Brew的旧维修收条':'Brew的新手练习录音')));assert.ok(t.clues.some(c=>c.title===(origin.seven==='shop'?'Seven的原始货签':'工坊的签收副本')));}}
function originChoices(o){const {brew,seven,june,mara,rivet}=o;return {brew,seven,june,mara,rivet};}
const {freshSequel:oldFresh,sequelView:oldView}=await import('./src/sequel-v6.js');let saved6=oldFresh('stay','two-part-routes-6',{});saved6.revision=87;sql.prepare('INSERT INTO saves(user_id,revision,payload,updated_at) VALUES(?,?,?,?)').run('old-sequel-v6',87,JSON.stringify(saved6),'2026-10-04');const loaded6=await(await call('/api/state','GET',null,'old-sequel-v6')).json();assert.equal(loaded6.revision,87);assert.equal(loaded6.version,'two-part-routes-6');assert.deepEqual(loaded6.scene,oldView(saved6).scene);assert.equal(loaded6.legacy,true);assert.equal((await(await call('/api/archives','GET',null,'old-sequel-v6')).json()).archives.length,0);assert.equal((await call('/api/choose','POST',{revision:87,choice:loaded6.choices[0].id},'old-sequel-v6')).status,200);
console.log('Novel: all 32 inheritance profiles on both separate routes, chapter-five convergence, full prose and pre-departure recharge; v6 sequel remains playable without reset.');
// Explicit continuation can recover the authenticated user's latest completed first-part archive.
const priorEnd=run('HE-stay');sql.prepare('INSERT INTO archives(id,user_id,payload,created_at) VALUES(?,?,?,?)').run('inherit-completed','inherit-user',JSON.stringify(priorEnd),'2026-10-04T16:00:00Z');const currentTrial=enterSequel(fresh(),'mobile');currentTrial.revision=125;sql.prepare('INSERT INTO saves(user_id,revision,payload,updated_at) VALUES(?,?,?,?)').run('inherit-user',125,JSON.stringify(currentTrial),'2026-10-04T16:01:00Z');const inherited=await(await call('/api/sequel','POST',{revision:125,route:'continue',confirm:true},'inherit-user')).json();assert.equal(inherited.route,'stay');assert.equal(inherited.revision,126);assert.equal(inherited.inheritance.demo,false);assert.equal(inherited.inheritance.choices.brew,view(priorEnd).stats.route===1?'repair':'practice');assert.equal((await call('/api/sequel','POST',{revision:0,route:'continue',confirm:true},'no-previous-first')).status,400);console.log('Explicit archived first-part continuation: real choices restored, owner isolated, CAS monotonic and no fabricated history.');
